1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>[必填] 替换为 PPT 标题 · Deck Title</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	<link href="https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600;700;800;900&family=JetBrains+Mono:wght@300;400;500;600&family=Noto+Sans+SC:wght@200;300;400;500;700;900&display=swap" rel="stylesheet">
10	<style>
11	  :root{
12	    /* ============ 主题色(默认: 🔵 克莱因蓝 IKB) ============
13	       切换主题: 从 references/themes-swiss.md 复制对应的 :root 块
14	       整体替换标有"主题色"注释的所有变量,其他散落的 var() 引用无需逐处改 */
15	    --paper:#fafaf8;          /* 主底色: 高级灰白 */
16	    --paper-rgb:250,250,248;
17	    --ink:#0a0a0a;            /* 文字主色: 近黑 */
18	    --ink-rgb:10,10,10;
19	    --grey-1:#f0f0ee;         /* 浅灰底 */
20	    --grey-2:#d4d4d2;         /* 中灰(分割线) */
21	    --grey-3:#737373;         /* 暗灰(辅助文字) */
22	    --accent:#002FA7;         /* 高亮色: 克莱因蓝 IKB */
23	    --accent-rgb:0,47,167;
24	    --accent-on:#ffffff;      /* accent 上的反色文字 */
25	    --accent-bright:#5B7BFF;  /* 暗底高亮: IKB 提亮版 */
26	
27	    /* ============ Carbon 文本角色 token (role-based,代替 opacity) ============
28	       亮底:  primary 主文 / secondary 次文 / helper 辅助 / placeholder 占位
29	       暗底:  inverse 自动反向 */
30	    --text-primary:#0a0a0a;        /* = ink, 100% */
31	    --text-secondary:#525252;      /* gray 70 */
32	    --text-helper:#737373;         /* gray 60 */
33	    --text-placeholder:#a3a3a3;    /* gray 40 */
34	    --text-on-color:#ffffff;       /* accent/dark 反色 */
35	    --border-subtle:#e0e0e0;       /* gray 20, 极细分隔 */
36	    --border-strong:#a3a3a3;       /* gray 40, 强分隔 */
37	
38	    /* ============ 字体(跨主题固定) ============ */
39	    --sans:"Inter","Helvetica Neue","Helvetica","Arial","Segoe UI Variable","Segoe UI",system-ui,-apple-system,sans-serif;
40	    --sans-zh:"PingFang SC","Hiragino Sans GB","Source Han Sans SC","Noto Sans SC","Microsoft YaHei UI","Microsoft YaHei","微软雅黑",sans-serif;
41	    --mono:"JetBrains Mono","IBM Plex Mono","SF Mono","Cascadia Code","Consolas","Courier New",ui-monospace,monospace;
42	
43	    /* ============ Carbon 2x Grid 间距模数 (基础 8px) ============
44	       参考: https://carbondesignsystem.com/elements/2x-grid/overview/
45	       任何 padding/gap/margin 优先用这套 token,确保 8px 基线对齐 */
46	    --sp-3:8px;     /* 02 token */
47	    --sp-4:12px;    /* 03 */
48	    --sp-5:16px;    /* 04 */
49	    --sp-6:24px;    /* 05 */
50	    --sp-7:32px;    /* 06 */
51	    --sp-8:40px;    /* 07 */
52	    --sp-9:48px;    /* 08 */
53	    --sp-10:64px;   /* 09 */
54	    --sp-11:80px;   /* 10 */
55	    --sp-12:96px;   /* 11 */
56	    --sp-13:160px;  /* 12 */
57	
58	    /* ============ Carbon Motion tokens ============
59	       https://carbondesignsystem.com/guidelines/motion/overview/
60	       两套体系:productive (功能) 短 + 锐 / expressive (叙事) 长 + 软 */
61	    --ease-prod:cubic-bezier(.2,0,.38,.9);          /* productive standard */
62	    --ease-exp:cubic-bezier(.4,.14,.3,1);            /* expressive standard */
63	    --ease-entry-prod:cubic-bezier(0,0,.38,.9);     /* productive entrance */
64	    --ease-entry-exp:cubic-bezier(0,0,.3,1);         /* expressive entrance */
65	    --dur-fast-1:.07s;   /* 70ms */
66	    --dur-fast-2:.11s;   /* 110ms */
67	    --dur-mod-1:.15s;    /* 150ms */
68	    --dur-mod-2:.24s;    /* 240ms */
69	    --dur-slow-1:.4s;    /* 400ms */
70	    --dur-slow-2:.7s;    /* 700ms */
71	
72	    /* 底部分页组件安全区: 主内容最低处不要进入这条区域 */
73	    --nav-safe-bottom:8vh;
74	  }
75	  *{box-sizing:border-box;margin:0;padding:0}
76	  html,body{
77	    width:100%;height:100%;overflow:hidden;
78	    background:var(--paper);color:var(--ink);
79	    font-family:var(--sans),var(--sans-zh);
80	    font-feature-settings:"ss01","cv11";
81	    -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility
82	  }
83	
84	  /* ============ WebGL 网格背景 ============ */
85	  canvas.bg{position:fixed;inset:0;width:100vw;height:100vh;z-index:0;display:block;opacity:.55;mix-blend-mode:multiply;pointer-events:none}
86	  body.dark-bg canvas.bg{mix-blend-mode:screen;opacity:.42}
87	  body.low-power canvas.bg,
88	  body.low-power canvas.ascii-bg{display:none!important}
89	
90	  /* ============ Deck 容器 + 翻页 ============ */
91	  #deck{position:fixed;inset:0;width:10000vw;height:100vh;display:flex;flex-wrap:nowrap;transition:transform .9s cubic-bezier(.77,0,.175,1);z-index:10;will-change:transform}
92	  .slide{
93	    width:100vw;height:100vh;flex:0 0 100vw;
94	    position:relative;
95	    padding:5.5vh 5vw 7vh 5vw;
96	    display:flex;flex-direction:column;
97	    overflow:hidden;
98	    background:var(--paper);color:var(--ink);
99	  }
100	  .slide.grey{background:var(--grey-1)}
101	  .slide.dark{background:var(--ink);color:var(--paper)}
102	  .slide.dark .grey-only{display:none}
103	  .slide.accent{background:var(--accent);color:var(--accent-on)}
104	  .slide.accent .accent-block{background:var(--accent-on);color:var(--accent)}
105	
106	  /* Hero 页透出网格背景多一点 */
107	  .slide.hero{background:transparent}
108	  .slide.hero.grey{background:rgba(var(--paper-rgb),.86);backdrop-filter:blur(1px)}
109	  .slide.hero.dark{background:rgba(var(--ink-rgb),.92);color:var(--paper)}
110	
111	  /* ============ 装饰: 极细分隔线 + 点阵矩阵 ============ */
112	  .rule{width:100%;height:1px;background:currentColor;opacity:.18;margin:0}
113	  .rule.thick{height:2px;opacity:.85}
114	  .rule.accent{background:var(--accent);opacity:1;height:2px}
115	  .rule.v{width:1px;height:100%;margin:0}
116	
117	  /* 点阵矩阵 (dot matrix) - 用 radial-gradient */
118	  .dots{
119	    background-image:radial-gradient(currentColor 1px, transparent 1px);
120	    background-size:12px 12px;

