506	  .geo-circle-o{width:.9vw;height:.9vw;border:2px solid currentColor;border-radius:50%;display:inline-block;vertical-align:middle}
507	
508	  /* ============ 图片 frame-img ============ */
509	  .frame-img{overflow:hidden;position:relative;background:var(--paper);box-sizing:border-box;width:100%}
510	  .slide.dark .frame-img{background:rgba(255,255,255,.06)}
511	  .frame-img > img{width:100%;height:100%;object-fit:cover;object-position:center center;display:block}
512	  .frame-img.fit-contain > img{object-fit:contain;object-position:center center}
513	  .frame-img.pos-top > img{object-position:top center}
514	  .frame-img.pos-face > img{object-position:center 35%}
515	  .frame-img.r-16x9{aspect-ratio:16/9;max-height:64vh}
516	  .frame-img.r-21x9{aspect-ratio:21/9;max-height:54vh}
