1337	<script>
1338	/* =============== WebGL 网格背景 (瑞士风专用) ===============
1339	   极简移动网格 + 微弱点阵叠加,营造"工业感、精准感"
1340	   - 主网格: 缓慢漂移的细线网格
1341	   - 次级: 鼠标附近的极细点阵微扰
1342	   - 颜色: 跟随主题(浅底深线 / 深底亮线),配合 mix-blend-mode
1343	*/
1344	const VS = `attribute vec2 position;void main(){gl_Position=vec4(position,0.0,1.0);}`;
1345	
1346	const FS = `precision highp float;
1347	uniform vec2 u_resolution;
1348	uniform float u_time;
1349	uniform vec2 u_mouse;
1350	uniform float u_dark; // 0 = light, 1 = dark
1351	uniform vec3 u_accent;
1352	
1353	float gridLine(vec2 uv, float spacing, float thickness){
1354	  vec2 g = abs(fract(uv / spacing) - 0.5);
1355	  float d = min(g.x, g.y);
1356	  return 1.0 - smoothstep(thickness - 0.005, thickness + 0.005, d);
1357	}
1358	
1359	float dot2(vec2 p){ return dot(p,p); }
1360	
1361	void main(){
1362	  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
1363	  float aspect = u_resolution.x / u_resolution.y;
1364	  vec2 p = uv;
1365	  p.x *= aspect;
1366	
1367	  // 缓慢平移
1368	  vec2 drift = vec2(u_time * 0.008, u_time * 0.005);
1369	  vec2 gp = p + drift;
1370	
1371	  // 主细网格 (大间距)
1372	  float mainGrid = gridLine(gp, 0.12, 0.012);
1373	  // 次级网格 (更细更密)
1374	  float subGrid = gridLine(gp, 0.024, 0.04) * 0.4;
1375	
1376	  // 鼠标附近的强化
1377	  vec2 m = u_mouse;
1378	  m.x *= aspect;
1379	  float md = length(p - m);
1380	  float mInfluence = exp(-md * 4.0) * 0.5;
1381	
1382	  float gridStrength = (mainGrid + subGrid * 0.5) * (0.45 + mInfluence);
1383	
1384	  // 点阵 (作为基底)
1385	  vec2 dotGrid = fract(gp * 50.0) - 0.5;
1386	  float dotMask = 1.0 - smoothstep(0.05, 0.14, length(dotGrid));
1387	  // 用低频噪声调制点阵密度
1388	  float wave = sin(gp.x * 1.4 + u_time * 0.15) * cos(gp.y * 1.6 - u_time * 0.12);
1389	  dotMask *= smoothstep(-0.3, 0.6, wave) * 0.6;
1390	
1391	  // 颜色: 浅底用深线条,深底用浅线条;高亮处带 accent 痕迹
1392	  vec3 lineColor = mix(vec3(0.08), vec3(0.92), u_dark);
1393	  vec3 bgColor = mix(vec3(0.97, 0.97, 0.96), vec3(0.06, 0.06, 0.07), u_dark);
1394	
1395	  // accent 暗示 (鼠标附近偷渡一点 accent 色)
1396	  vec3 col = bgColor;
1397	  col = mix(col, lineColor, gridStrength * 0.55);
1398	  col = mix(col, lineColor, dotMask * 0.35);
1399	  col = mix(col, u_accent, mInfluence * 0.18);
1400	
1401	  gl_FragColor = vec4(col, 1.0);
1402	}`;
