1433	  // 读取 CSS 变量,把 accent 颜色塞进 shader
1434	  function readAccent(){
1435	    const cs = getComputedStyle(document.documentElement);
1436	    const hex = cs.getPropertyValue('--accent').trim() || '#002FA7';
1437	    const m = hex.match(/^#([0-9a-f]{6})$/i);
1438	    if(!m) return [0, 0.18, 0.65];
1439	    const n = parseInt(m[1], 16);
1440	    return [((n>>16)&255)/255, ((n>>8)&255)/255, (n&255)/255];
1441	  }
1442	  let accent = readAccent();
1443	  let dark = 0;
1444	
1445	  return (tSec, isDark)=>{
1446	    if(isDark !== undefined) dark = isDark ? 1 : 0;
1447	    accent = readAccent();
1448	    gl.uniform2f(lRes,canvas.width,canvas.height);
1449	    gl.uniform1f(lT,tSec);
1450	    gl.uniform2f(lM,mouse.x,mouse.y);
1451	    gl.uniform1f(lD,dark);
1452	    gl.uniform3f(lA,accent[0],accent[1],accent[2]);
1453	    gl.drawArrays(gl.TRIANGLES,0,6);
1454	    return true;
1455	  };
1456	}
1457	// canvas-mode / low-power: skip WebGL draw loop (no active RAF loop)
