2314	<script>
2315	/* ============== ASCII 点阵呼吸场 · IKB 封面/封底专用 ==============
2316	   sin/cos 二维噪声场驱动字符显隐,营造工业仪表板的"涌动呼吸"质感.
2317	   纯 canvas 2D, mix-blend-mode:screen 让字符在 IKB 底色上自然发亮.
2318	   用法:在需要呼吸场的容器(.canvas-card 或 split .half.b-accent)内首位插入
2319	        <canvas class="ascii-bg" aria-hidden="true">,本脚本会自动扫描并启动. */
2320	(function(){
2321	  const canvases = [...document.querySelectorAll('canvas.ascii-bg')];
2322	  if(!canvases.length) return;
2323	
2324	  const PALETTE = '   ...:::---+++***◦◦••▢▣';
2325	  const CELL = 16;
2326	  const FONT_SIZE = 13;
2327	
2328	  function setup(c){
2329	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
2330	    const rect = c.getBoundingClientRect();
2331	    if(rect.width < 4 || rect.height < 4) return false;
2332	    c.width = Math.round(rect.width * dpr);
2333	    c.height = Math.round(rect.height * dpr);
2334	    c.__dpr = dpr;
2335	    c.__w = rect.width;
2336	    c.__h = rect.height;
2337	    const ctx = c.getContext('2d');
2338	    ctx.setTransform(dpr,0,0,dpr,0,0);
2339	    const mono = (getComputedStyle(document.documentElement).getPropertyValue('--mono') || 'JetBrains Mono, monospace').trim();
2340	    ctx.font = `500 ${FONT_SIZE}px ${mono}`;
2341	    ctx.textBaseline = 'top';
2342	    c.__ctx = ctx;
2343	    return true;
2344	  }
2345	
2346	  function draw(c, t){
2347	    if(!c.__ctx) return;
2348	    const ctx = c.__ctx, w = c.__w, h = c.__h;
2349	    ctx.clearRect(0, 0, w, h);
2350	    const cols = Math.ceil(w / CELL);
2351	    const rows = Math.ceil(h / CELL);
2352	    for(let r=0; r<rows; r++){
2353	      for(let cc=0; cc<cols; cc++){
2354	        const n = (
2355	          Math.sin(cc * 0.18 + t) +
2356	          Math.sin(r * 0.24 - t * 0.7) +
2357	          Math.sin((cc + r) * 0.12 + t * 0.45) +
2358	          Math.sin(Math.hypot(cc - cols * 0.5, r - rows * 0.5) * 0.16 - t * 0.55)
2359	        ) / 4; // [-1, 1]
2360	        const v = (n + 1) / 2; // [0, 1]
2361	        if(v < 0.22) continue;
2362	        const idx = Math.min(PALETTE.length - 1, Math.floor(v * PALETTE.length));
2363	        const ch = PALETTE[idx];
2364	        if(ch === ' ') continue;
2365	        const alpha = 0.08 + (v - 0.22) * 0.55;
2366	        ctx.fillStyle = `rgba(255,255,255,${alpha.toFixed(3)})`;
2367	        ctx.fillText(ch, cc * CELL, r * CELL);
2368	      }
2369	    }
2370	  }
2371	
2372	  function resizeAll(){ canvases.forEach(setup); }
2373	  let pending = null;
2374	  window.addEventListener('resize', ()=>{
