/* recipe: system-diagram */
function rSystemDiagram(slide, all){
  const head = slide.querySelector('[data-anim="head"]');
  if(head) fade(head, {duration:.55, y:10});
  const stage = slide.querySelector('[data-anim="up"]');
  if(!stage) return;
  animate(stage, {opacity:[0,1]}, {duration:.3, delay:.35, easing:EASE_PROD});
  const svgs = [...stage.querySelectorAll('svg')];
  svgs.forEach((svg, i)=>{
    const base = .55 + i*.22;
    const circles = [...svg.querySelectorAll('circle')];
    if(circles.length > 1){
      circles.forEach((c, j)=>{
        c.style.transformOrigin = `${c.getAttribute('cx')}px ${c.getAttribute('cy')}px`;
        animate(c, {opacity:[0,1], scale:[.4, 1]},
          {duration:.5, delay:base + j*.13, easing:EASE_ENTRY_EXP});
      });
    } else if(circles[0]){
      circles[0].style.transformOrigin = `${circles[0].getAttribute('cx')}px ${circles[0].getAttribute('cy')}px`;
      animate(circles[0], {opacity:[0,1], scale:[.4, 1]},
        {duration:.5, delay:base, easing:EASE_ENTRY_EXP});
    }
    const labels = [...svg.querySelectorAll('text')];
    labels.forEach((t, j)=>{
      animate(t, {opacity:[0,1]}, {duration:.4, delay:base + .25 + j*.06, easing:EASE_PROD});
    });
  });
  const descCols = [...stage.querySelectorAll(':scope > div:first-child > div')];
  descCols.forEach((col, i)=>{
    animate(col, {opacity:[0,1], y:[12, 0]}, {duration:.45, delay:1.0 + i*.1, easing:EASE_ENTRY_EXP});
  });
}

/* recipe: split-statement - closing */
function rSplitStatement(slide, all){
  const halves = [...slide.querySelectorAll('.half')];
  if(halves[0]){
    animate(halves[0], {opacity:[0,1]}, {duration:.4, easing:EASE_PROD});
  }
  if(halves[1]){
    animate(halves[1], {opacity:[0,1]}, {duration:.4, delay:.3, easing:EASE_PROD});
  }
  const manifesto = slide.querySelector('[data-anim="manifesto"]');
  if(manifesto) animate(manifesto, {opacity:[0,1], y:[18, 0]}, {duration:.7, delay:.2, easing:EASE_ENTRY_EXP});
  const signature = slide.querySelector('[data-anim="signature"]');
  if(signature) animate(signature, {opacity:[0,1]}, {duration:.4, delay:.8, easing:EASE_PROD});
  const rules = slide.querySelector('[data-anim="rules"]');
  if(rules){
    const items = [...rules.children];
    items.forEach((item, i)=>{
      animate(item, {opacity:[0,1], x:[20, 0]},
        {duration:.45, delay:.6 + i*.12, easing:EASE_ENTRY_EXP});
    });
  }
  const foot = slide.querySelector('[data-anim="foot"]');
  if(foot) animate(foot, {opacity:[0,1]}, {duration:.3, delay:1.3, easing:EASE_PROD});
}

