function rArchPanorama(slide, all){
  const head = slide.querySelector('[data-anim="head"]');
  if(head) fade(head, {duration:.55, y:10});
  const stage = slide.querySelector('[data-anim="up"]');
  if(!stage) return;
  animate(stage, {opacity:[0,1]}, {duration:.4, delay:.35, easing:EASE_PROD});

  /* SVG: draw paths + fade in */
  const svg = stage.querySelector('svg');
  if(svg){
    const paths = svg.querySelectorAll('path');
    paths.forEach((p, i)=>{
      const len = 300;
      p.style.strokeDasharray = len;
      p.style.strokeDashoffset = len;
      animate(p, {strokeDashoffset:[len, 0]}, {duration:.6, delay:.45 + i*.06, easing:EASE_ENTRY_EXP});
    });
    animate(svg, {opacity:[0,1]}, {duration:.4, delay:.45, easing:EASE_PROD});
  }

  /* Architecture cards by column: col1 -> col2 -> col3 staggered */
  const col1 = stage.querySelectorAll('[data-anim="col1"]');
  const col2 = stage.querySelectorAll('[data-anim="col2"]');
  const col3 = stage.querySelectorAll('[data-anim="col3"]');
  [col1, col2, col3].forEach((cols, ci)=>{
    cols.forEach((card, ri)=>{
      animate(card, {opacity:[0,1], y:[14, 0]},
        {duration:.5, delay:.7 + ci*.1 + ri*.08, easing:EASE_ENTRY_EXP});
    });
  });

  /* Legend */
  const legend = slide.querySelector('[data-anim="legend"]');
  if(legend) animate(legend, {opacity:[0,1]}, {duration:.3, delay:1.6, easing:EASE_PROD});
}

